mapper.select:
/*
    SQL ID : MarkSubjectDAO.mrkSbjctList
    설  명 : 학생들의 성적 목록 조회 (markSubjectVO)
*/
SELECT B.*
FROM TB_LMS_ATNDLC A
LEFT JOIN TB_LMS_SBJCT_MRK B ON A.SBJCT_ID = B.SBJCT_ID AND A.USER_ID = B.USER_ID
WHERE A.SBJCT_ID = #{sbjctId}

    AND A.USER_ID IN

        #{userId}

/* SQL ID : MarkSubjectDAO.mrkSbjctDtlList 설 명 : 학생들의 성적 상세 목록 조회 (subjectMarkDetailVO) */ SELECT B.SBJCT_ID , B.SBJCT_MRK_ID , C.SBJCT_MRK_DTL_ID , B.USER_ID , C.MRK_ITM_TYCD , NVL(C.ACQS_SCR, 0) AS ACQS_SCR FROM TB_LMS_ATNDLC A JOIN TB_LMS_SBJCT_MRK B ON A.SBJCT_ID = B.SBJCT_ID AND A.USER_ID = B.USER_ID JOIN TB_LMS_SBJCT_MRK_DTL C ON B.SBJCT_MRK_ID = C.SBJCT_MRK_ID WHERE A.SBJCT_ID = #{sbjctId}
AND A.USER_ID IN
#{userId}

/* SQL ID : MarkSubjectDAO.stdSbjctMrkList 설 명 : 학생들의 성적 목록 조회 */ WITH SCORE_INFO AS ( SELECT MRK.SBJCT_ID , MRK.USER_ID , MRK.SCR_CNVS_STSCD , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'MIDEXAM' THEN ACQS_SCR END) AS MIDEXAM_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'MIDEXAM' THEN DRVTN_SCR END) AS MIDEXAM_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'LSTEXAM' THEN ACQS_SCR END) AS LSTEXAM_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'LSTEXAM' THEN DRVTN_SCR END) AS LSTEXAM_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'EXAM' THEN ACQS_SCR END) AS EXAM_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'EXAM' THEN DRVTN_SCR END) AS EXAM_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'PRG' THEN ACQS_SCR END) AS PRG_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'PRG' THEN DRVTN_SCR END) AS PRG_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'EXRCS_QSTN' THEN ACQS_SCR END) AS EXRCS_QSTN_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'EXRCS_QSTN' THEN DRVTN_SCR END) AS EXRCS_QSTN_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'ASMT' THEN ACQS_SCR END) AS ASMT_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'ASMT' THEN DRVTN_SCR END) AS ASMT_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'DSCS' THEN ACQS_SCR END) AS DSCS_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'DSCS' THEN DRVTN_SCR END) AS DSCS_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'QUIZ' THEN ACQS_SCR END) AS QUIZ_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'QUIZ' THEN DRVTN_SCR END) AS QUIZ_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'SRVY' THEN ACQS_SCR END) AS SRVY_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'SRVY' THEN DRVTN_SCR END) AS SRVY_DRVTN_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'SMNR' THEN ACQS_SCR END) AS SMNR_ACQS_SCR , MAX(CASE WHEN DTL.MRK_ITM_TYCD = 'SMNR' THEN DRVTN_SCR END) AS SMNR_DRVTN_SCR , SUM(DTL.ACQS_SCR ) AS TOT_ACQS_SCR , MRK.TOT_SCR , MRK.ADTN_SCR , MRK.ETC_SCR , MRK.LST_SCR FROM TB_LMS_SBJCT_MRK MRK JOIN TB_LMS_SBJCT_MRK_DTL DTL ON MRK.SBJCT_MRK_ID = DTL.SBJCT_MRK_ID WHERE 1=1 AND MRK.SBJCT_ID = #{sbjctId} AND DTL.MRK_ITM_TYCD IN ( SELECT MRK_ITM_TYCD FROM TB_LMS_MRK_ITM_STNG X WHERE X.SBJCT_ID = MRK.SBJCT_ID ) GROUP BY MRK.SBJCT_ID , MRK.USER_ID, MRK.SCR_CNVS_STSCD, MRK.TOT_SCR, MRK.ADTN_SCR, MRK.ETC_SCR, MRK.LST_SCR, MRK.LST_SCR ) SELECT ROW_NUMBER() OVER(ORDER BY USR.USERNM) AS LINE_NO , (SELECT DEPTNM FROM TB_LMS_DEPT X WHERE X.DEPT_ID = SBJ.DEPT_ID) AS DEPTNM , USR.USER_ID , USR.USER_RPRS_ID , USR.STDNT_NO , USR.USERNM , STD.SBJCT_ID , SCR.* FROM TB_LMS_USER USR JOIN TB_LMS_ATNDLC STD ON STD.USER_ID = USR.USER_ID JOIN TB_LMS_SBJCT SBJ ON STD.SBJCT_ID = SBJ.SBJCT_ID LEFT JOIN SCORE_INFO SCR ON STD.USER_ID = SCR.USER_ID AND SBJ.SBJCT_ID = SCR.SBJCT_ID WHERE 1=1 AND STD.SBJCT_ID = #{sbjctId}
AND STD.USER_ID IN (
#{userId}
)

mapper.delete:
/*
    SQL ID: markSubjectDAO.allStdMrkSbjctDelete
    설  명 : 해당 과목의 모든 학생 성적 데이터를 삭제한다.
*/
DELETE FROM TB_LMS_SBJCT_MRK SBJ
WHERE SBJ.USER_ID IN (
    SELECT USER_ID
    FROM TB_LMS_ATNDLC STD
    WHERE STD.SBJCT_ID = #{sbjctId}
)

/*
    SQL ID: markSubjectDAO.allStdMrkSbjctDtlDelete
    설  명 : 해당 과목의 모든 학생 성적 상세 데이터를 삭제한다.
*/
DELETE FROM TB_LMS_SBJCT_MRK_DTL DTL
WHERE DTL.SBJCT_MRK_ID IN (
    SELECT X.SBJCT_MRK_ID
    FROM TB_LMS_SBJCT_MRK X
    WHERE X.SBJCT_ID = #{sbjctId}
)

mapper.insert:
/*
    SQL ID : markSubjectDAO.mrkSbjctBatchInsert
    설  명 : 학생들의 성적과목 데이터를 등록한다.
*/

    INSERT INTO TB_LMS_SBJCT_MRK (
          SBJCT_MRK_ID
        , USER_ID
        , SBJCT_ID
        , SCR_CNVS_STSCD
        , RGTR_ID
        , REG_DTTM
        , TOT_SCR
        , LST_SCR
        , ADTN_SCR
    )VALUES (
          #{item.sbjctMrkId}
        , #{item.userId}
        , #{item.sbjctId}
        , #{item.scrCnvsStscd}
        , #{item.rgtrId}
        , FN_DTTM()
        , #{item.totScr}
        , #{item.lstScr}
        , #{item.adtnScr}
    )

/*
    SQL ID : markSubjectDAO.mrkSbjctDtlBatchInsert
    설  명 : 학생들의 성적과목 상세 데이터를 등록한다.
*/

    INSERT INTO TB_LMS_SBJCT_MRK_DTL (
          SBJCT_MRK_DTL_ID
        , SBJCT_MRK_ID
        , MRK_ITM_TYCD
        , ACQS_SCR
        , DRVTN_SCR
        , RGTR_ID
        , REG_DTTM
    )VALUES (
          #{item.sbjctMrkDtlId}
        , #{item.sbjctMrkId}
        , #{item.mrkItmTycd}
        , #{item.acqsScr}
        , #{item.drvtnScr}
        , #{item.rgtrId}
        , FN_DTTM()
    )

mapper.select:
/* SQL ID : markSubjectDAO.mrkProcExcpProcList 설 명 : 과목별 성적처리 예외처리 목록(페이징) 조회한다. - 최근건 노출 */ WITH BASE_INFO AS ( SELECT ORG.ORG_ID , ORG.ORGNM , SMSTR.SMSTR_CHRT_GBNCD , SMSTR.DGRS_YR , SMSTR.DGRS_SMSTR_CHRT , (CASE WHEN NVL(SMSTR.SMSTR_CHRT_GBNCD, 'SMSTR') = 'SMSTR' THEN SMSTR.DGRS_SMSTR_CHRT || '학기' ELSE SMSTR.DGRS_SMSTR_CHRT || '기' END) AS DGRS_SMSTR , SBJ.SBJCT_ID , SBJ.SBJCTNM , SBJ.CRCLMN_NO , SBJ.DVCLAS_NO FROM TB_LMS_SBJCT SBJ JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON SMSTR.ORG_ID = ORG.ORG_ID ORDER BY SMSTR.DGRS_YR DESC, SMSTR.DGRS_SMSTR_CHRT DESC, SMSTR.SMSTR_CHRT_GBNCD DESC , ORG.ORGNM ASC, SBJ.SBJCTNM ASC ), SBJCT_ADM_LIST AS ( SELECT ADM.SBJCT_ID, ADM.USER_ID, USR.USERNM , ADM.SBJCT_ADM_TYCD, ADM.SBJCT_ADM_SEQNO FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_USER USR ON ADM.USER_ID = USR.USER_ID WHERE ADM.SBJCT_ADM_SEQNO = 1 ), EXCP_INFO AS ( SELECT ROW_NUMBER() OVER(PARTITION BY EXCP.SBJCT_ID ORDER BY EXCP.REG_DTTM DESC) AS RN , EXCP.* FROM TB_LMS_MRK_PROC_EXCP_PROC EXCP )
SELECT ROW_NUMBER() OVER(ORDER BY BASE.DGRS_YR DESC, BASE.DGRS_SMSTR_CHRT DESC, BASE.SMSTR_CHRT_GBNCD DESC, BASE.ORGNM ASC, BASE.SBJCTNM ASC) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT , BASE.* , PROF.USERNM AS PROFNM , TUT.USERNM AS TUTNM , EXCP.MRK_PROC_EXCP_PROC_ID , EXCP.PROC_SDTTM , EXCP.PROC_EDTTM , EXCP.PROC_RSN , EXCP.REG_DTTM FROM BASE_INFO BASE LEFT JOIN EXCP_INFO EXCP ON BASE.SBJCT_ID = EXCP.SBJCT_ID AND EXCP.RN = 1 -- 교수 LEFT JOIN SBJCT_ADM_LIST PROF ON BASE.SBJCT_ID = PROF.SBJCT_ID AND PROF.SBJCT_ADM_TYCD = 'PROF' -- 튜터 LEFT JOIN SBJCT_ADM_LIST TUT ON BASE.SBJCT_ID = TUT.SBJCT_ID AND TUT.SBJCT_ADM_TYCD = 'TUT' WHERE 1=1
AND BASE.ORG_ID = #{orgId}
AND BASE.SMSTR_CHRT_GBNCD = #{smstrChrtGbncd}
AND BASE.DGRS_YR = #{dgrsYr}
AND BASE.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND BASE.SBJCT_ID = #{sbjctId}
AND ( LOWER(BASE.SBJCTNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(BASE.CRCLMN_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(PROF.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(PROF.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )

/* SQL ID : markSubjectDAO.allMrkProcExcpProcListPaging 설 명 : 성적처리 예외처리 건 목록(페이징) 조회한다. - 전체건 노출 */ WITH BASE_INFO AS ( SELECT ORG.ORG_ID , ORG.ORGNM , SMSTR.SMSTR_CHRT_GBNCD , SMSTR.DGRS_YR , SMSTR.DGRS_SMSTR_CHRT , (CASE WHEN NVL(SMSTR.SMSTR_CHRT_GBNCD, 'SMSTR') = 'SMSTR' THEN SMSTR.DGRS_SMSTR_CHRT || '학기' ELSE SMSTR.DGRS_SMSTR_CHRT || '기' END) AS DGRS_SMSTR , SBJ.SBJCT_ID , SBJ.SBJCTNM , SBJ.CRCLMN_NO , SBJ.DVCLAS_NO FROM TB_LMS_SBJCT SBJ JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON SMSTR.ORG_ID = ORG.ORG_ID ), SBJCT_ADM_LIST AS ( SELECT ADM.SBJCT_ID, ADM.USER_ID, USR.USERNM , ADM.SBJCT_ADM_TYCD, ADM.SBJCT_ADM_SEQNO FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_USER USR ON ADM.USER_ID = USR.USER_ID WHERE ADM.SBJCT_ADM_SEQNO = 1 ), EXCP_INFO AS ( SELECT ROW_NUMBER() OVER(PARTITION BY EXCP.SBJCT_ID ORDER BY EXCP.REG_DTTM DESC) AS RN , EXCP.* FROM TB_LMS_MRK_PROC_EXCP_PROC EXCP )
SELECT ROW_NUMBER() OVER(ORDER BY EXCP.REG_DTTM ASC) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT , BASE.* , PROF.USERNM AS PROFNM , EXCP.PROC_SDTTM , EXCP.PROC_EDTTM , EXCP.REG_DTTM , EXCP.RGTR_ID , USR.USERNM AS PROCNM , CASE WHEN EXCP.RN = 1 THEN '등록' ELSE '수정' END AS PROC_STS FROM BASE_INFO BASE JOIN EXCP_INFO EXCP ON BASE.SBJCT_ID = EXCP.SBJCT_ID -- 교수 LEFT JOIN SBJCT_ADM_LIST PROF ON BASE.SBJCT_ID = PROF.SBJCT_ID AND PROF.SBJCT_ADM_TYCD = 'PROF' -- 튜터 -- LEFT JOIN SBJCT_ADM_LIST TUT ON BASE.SBJCT_ID = TUT.SBJCT_ID AND TUT.SBJCT_ADM_TYCD = 'TUT' -- 처리자 JOIN TB_LMS_USER USR ON EXCP.RGTR_ID = USR.USER_ID WHERE 1=1
AND BASE.ORG_ID = #{orgId}
AND BASE.SMSTR_CHRT_GBNCD = #{smstrChrtGbncd}
AND BASE.DGRS_YR = #{dgrsYr}
AND BASE.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND BASE.SBJCT_ID = #{sbjctId}
AND ( LOWER(BASE.SBJCTNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(BASE.CRCLMN_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(PROF.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(PROF.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )

mapper.insert:
/*
    SQL ID : markSubjectDAO.mrkProcExcpProcListBatchInsert
    설  명 : 성적처리 예외처리 건을 일괄 등록한다.
*/

    INSERT INTO TB_LMS_MRK_PROC_EXCP_PROC (
          MRK_PROC_EXCP_PROC_ID
        , SBJCT_ID
        , PROC_SDTTM
        , PROC_EDTTM
        , PROC_RSN
        , RGTR_ID
        , REG_DTTM
    )VALUES (
          #{item.mrkProcExcpProcId}
        , #{item.sbjctId}
        , #{item.procSdttm}
        , #{item.procEdttm}
        , #{item.procRsn}
        , #{item.rgtrId}
        , FN_DTTM()
    )

mapper.delete:
/*
    SQL ID : markSubjectDAO.mrkProcExcpProcListBatchDelete
    설  명 : 성적처리 예외처리 건을 일괄 삭제한다.
*/

    DELETE FROM TB_LMS_MRK_PROC_EXCP_PROC
    WHERE MRK_PROC_EXCP_PROC_ID = #{item.mrkProcExcpProcId}
    AND SBJCT_ID = #{item.sbjctId}
